package com.javacodingagent.bootstrap;
import com.fasterxml.jackson.databind.ObjectMapper; import com.javacodingagent.api.task.*; import com.javacodingagent.api.repository.InMemoryRepositoryService; import com.javacodingagent.api.trace.TaskEventBroker; import com.javacodingagent.core.*; import com.javacodingagent.core.llm.*; import com.javacodingagent.infrastructure.model.OpenAiCompatibleCodingModel; import com.javacodingagent.trace.*; import io.micrometer.core.instrument.MeterRegistry; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import java.util.concurrent.*;
@Configuration public class AgentBeans { @Bean InMemoryTaskService taskService() { return new InMemoryTaskService(); } @Bean InMemoryRepositoryService repositoryService() { return new InMemoryRepositoryService(); }
 @Bean CodingModel codingModel(@Value("${coding-agent.llm.base-url:}") String baseUrl, @Value("${coding-agent.llm.api-key:}") String apiKey, @Value("${coding-agent.llm.model-name:}") String modelName, ObjectMapper mapper) { return apiKey.isBlank() || baseUrl.isBlank() || modelName.isBlank() ? new DeterministicCodingModel() : new OpenAiCompatibleCodingModel(baseUrl, apiKey, modelName, mapper); }
 @Bean TraceStore traceStore() { return new InMemoryTraceStore(); } @Bean TaskEventBroker taskEventBroker() { return new TaskEventBroker(); } @Bean(destroyMethod="shutdown") ExecutorService agentExecutor() { return Executors.newFixedThreadPool(Math.max(2, Runtime.getRuntime().availableProcessors() / 2)); } @Bean TaskOrchestrator taskOrchestrator(InMemoryTaskService tasks, InMemoryRepositoryService repositories, CodingAgentEngine engine, TaskEventBroker events, ExecutorService agentExecutor) { return new TaskOrchestrator(tasks, repositories, engine, events, agentExecutor); } @Bean AgentMetrics agentMetrics(MeterRegistry registry) { return new AgentMetrics(registry); } @Bean Supervisor supervisor(CodingModel model) { return new Supervisor(model); } @Bean CodingAgentEngine codingAgentEngine(CodingModel model, TraceStore traces) { return new CodingAgentEngine(model, traces); } }
